# Validation entrypoint for the final Osceola browser snapshot.
import base64,gzip,json,re
from pathlib import Path
PAYLOAD=''
raw=gzip.decompress(base64.b64decode(PAYLOAD)); data=json.loads(raw)
Path('data/osceola.json').write_text(json.dumps(data,indent=2)+'\n')
state=json.loads(Path('data/statewide.json').read_text())
def key(s): return re.sub(r'[^a-z0-9]','',s.lower())
checks=[]
for race in data['races']:
 src=race['sourceContestName']
 if not (src.startswith('REP ') or src.startswith('DEM ')) or not any(x in src for x in ['United States Senator','Governor and Lieutenant Governor','Chief Financial Officer','Commissioner of Agriculture']): continue
 sr=next((x for x in state['races'] if x['name']==src),None); assert sr,src
 geo=next((g for g in sr.get('geography',[]) if g.get('county')=='Osceola'),None); assert geo,src
 dos={key(n):int(v) for n,v in geo['votes'].items()}; local={key(c['name']):int(c['votes']) for c in race['candidates']}
 assert set(dos)==set(local),src
 ds={n:local[n]-dos[n] for n in local}; assert all(0<=d<=50 for d in ds.values()),(src,ds); checks.append({'race':src,'maxDelta':max(ds.values())})
assert len(checks)==8,checks
d9=json.loads(Path('data/district-9.json').read_text()); race=next(r for r in data['races'] if 'Representative in Congress - District 9' in r['name']); local={key(c['name']):int(c['votes']) for c in race['candidates']}; geo=None
for r in d9.get('races',[]):
 for g in r.get('geography',[]):
  if g.get('county')=='Osceola': geo=g; break
 if geo: break
assert geo
dos={key(n):int(v) for n,v in geo['votes'].items()}; assert set(dos)==set(local); ds={n:local[n]-dos[n] for n in local}; assert all(0<=d<=10 for d in ds.values()),ds
m=json.loads(Path('data/manifest.json').read_text()); m['counties']['Osceola']={'connected':True,'file':'data/osceola.json','sourceUrl':data['sourceUrl'],'races':len(data['races']),'adapter':'v2-clarity-browser-json-validated','validationFailed':False,'frozenElection':True,'coverageComplete':True,'clarityVersion':'378698','validatedAgainst':'Florida DOS statewide county geography + District 9 geography'}; Path('data/manifest.json').write_text(json.dumps(m,indent=2)+'\n')
report={'passed':True,'races':len(data['races']),'statewideChecks':checks,'cd9MaxDelta':max(ds.values()),'coverageComplete':True}; Path('osceola-final-validation.json').write_text(json.dumps(report,indent=2)+'\n'); print(json.dumps(report,indent=2))
